#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>

#define MAX_TOKEN_LEN 512
#define MAX_USERNAME_LEN 64
#define MIN_SECRET_KEY_LEN 16

typedef struct {
    char username[MAX_USERNAME_LEN];
    uint32_t issued_at;
    uint32_t expires_at;
    uint16_t privilege_level;
    uint16_t session_flags;
} session_data_t;

typedef struct {
    session_data_t data;
    unsigned char mac[32];
} auth_token_t;

/* Retrieve the HMAC secret from a secure external source (environment).
 * Never hardcode secrets in source. Fails closed if missing/too weak. */
static const char *get_secret_key(size_t *out_len) {
    const char *key = getenv("AUTH_TOKEN_SECRET");
    if (!key) return NULL;
    size_t len = strlen(key);
    if (len < MIN_SECRET_KEY_LEN) return NULL;
    if (out_len) *out_len = len;
    return key;
}

/* Compute HMAC-SHA256 over session data */
static int compute_mac(const session_data_t *data, unsigned char *out_mac) {
    size_t key_len = 0;
    const char *secret = get_secret_key(&key_len);
    if (!secret) return 0; /* fail closed if no valid secret configured */

    unsigned int mac_len = 0;
    unsigned char *result = HMAC(EVP_sha256(), secret, (int)key_len,
                                 (const unsigned char *)data, sizeof(session_data_t),
                                 out_mac, &mac_len);
    return result != NULL && mac_len == 32;
}

/* Constant-time comparison to prevent timing attacks */
static int secure_compare(const unsigned char *a, const unsigned char *b, size_t len) {
    volatile unsigned char result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

/* Validate username contains only safe characters */
static int validate_username(const char *username) {
    size_t len = strnlen(username, MAX_USERNAME_LEN);
    if (len == 0 || len >= MAX_USERNAME_LEN) return 0;
    for (size_t i = 0; i < len; i++) {
        char c = username[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '.')) {
            return 0;
        }
    }
    return 1;
}

/* Create a new authenticated session token */
int create_token(const char *username, uint16_t privilege_level, auth_token_t *token) {
    if (!username || !token) return -1;
    if (!validate_username(username)) return -1;

    memset(token, 0, sizeof(auth_token_t));
    strncpy(token->data.username, username, MAX_USERNAME_LEN - 1);
    token->data.issued_at = (uint32_t)time(NULL);
    token->data.expires_at = token->data.issued_at + 3600; /* 1 hour */
    token->data.privilege_level = privilege_level;
    token->data.session_flags = 0x0001; /* active flag */

    if (!compute_mac(&token->data, token->mac)) return -1;
    return 0;
}

/* Verify token integrity and check authorization level */
static int verify_token_mac(const auth_token_t *token) {
    unsigned char expected_mac[32];
    if (!compute_mac(&token->data, expected_mac)) return 0;
    return secure_compare(token->mac, expected_mac, 32);
}

/* Check if the requesting user has sufficient privileges for an action.
 * Required privilege is computed as base_level + resource_modifier.
 * Uses 32-bit arithmetic to avoid truncation issues. */
static int check_privilege(const auth_token_t *token, uint32_t required_base, uint32_t resource_modifier) {
    /* Compute effective required privilege level in 32-bit to prevent overflow */
    uint32_t effective_required = required_base + resource_modifier;

    /* Cap at max representable privilege to prevent wrap-around */
    if (effective_required > 65535) {
        effective_required = 65535;
    }

    /* User's privilege must meet or exceed the requirement */
    if ((uint32_t)token->data.privilege_level >= effective_required) {
        return 1;
    }
    return 0;
}

/* Main authorization check combining MAC verification, expiry, and privilege */
int authorize_request(const auth_token_t *token, const char *resource, uint32_t action_level) {
    if (!token || !resource) return 0;

    /* Step 1: Verify MAC integrity */
    if (!verify_token_mac(token)) {
        return 0;
    }

    /* Step 2: Check token hasn't expired */
    uint32_t now = (uint32_t)time(NULL);
    if (now > token->data.expires_at) {
        return 0;
    }

    /* Step 3: Check session is active */
    if (!(token->data.session_flags & 0x0001)) {
        return 0;
    }

    /* Step 4: Compute resource-specific modifier based on resource path hash */
    uint32_t resource_modifier = 0;
    size_t rlen = strlen(resource);
    for (size_t i = 0; i < rlen; i++) {
        resource_modifier = (resource_modifier * 31 + (unsigned char)resource[i]) & 0xFFFF;
    }

    /* Step 5: Check privilege level with resource modifier */
    /* Admin resources (starting with /admin) require base level 1000 + modifier */
    /* Regular resources require base level 100 + modifier */
    uint32_t base_level;
    if (rlen >= 6 && strncmp(resource, "/admin", 6) == 0) {
        base_level = 1000;
    } else {
        base_level = 100;
    }

    return check_privilege(token, base_level, resource_modifier);
}

/* Serialize token to hex string for transport */
int token_to_hex(const auth_token_t *token, char *out, size_t out_size) {
    size_t needed = sizeof(auth_token_t) * 2 + 1;
    if (out_size < needed) return -1;

    const unsigned char *bytes = (const unsigned char *)token;
    for (size_t i = 0; i < sizeof(auth_token_t); i++) {
        sprintf(out + i * 2, "%02x", bytes[i]);
    }
    return 0;
}

/* Deserialize token from hex string */
int hex_to_token(const char *hex, auth_token_t *token) {
    size_t hex_len = strlen(hex);
    if (hex_len != sizeof(auth_token_t) * 2) return -1;

    unsigned char *bytes = (unsigned char *)token;
    for (size_t i = 0; i < sizeof(auth_token_t); i++) {
        unsigned int byte_val;
        char h = hex[i * 2];
        char l = hex[i * 2 + 1];
        /* Reject any non-hex-digit characters (%x otherwise accepts
         * whitespace and sign chars, corrupting the round-trip). */
        if (!isxdigit((unsigned char)h) || !isxdigit((unsigned char)l)) return -1;
        if (sscanf(hex + i * 2, "%2x", &byte_val) != 1) return -1;
        bytes[i] = (unsigned char)byte_val;
    }
    return 0;
}
